import {dataFetch} from './data-source.js';
import './i18n.js';
import {bindContextOpacity} from './context-opacity.js';
import {createCellView,components} from './scene.js';
const $=s=>document.querySelector(s);const icons=()=>window.lucide.createIcons();
const metrics=[
 {id:'mass',title:'生长',label:'细胞干质量',unit:'fg',icon:'sprout',color:'#927957',description:'细胞干质量随时间的变化，不包含水分。质量来自模型的 mass listener。'},
 {id:'rna',title:'转录',label:'mRNA 数量',unit:'mRNA',icon:'waves',color:'#ab738a',description:'所有 mRNA 转录单元的分子数总和。可同时观察活跃 RNA 聚合酶与 RNA 总质量。'},
 {id:'ribosomes',title:'翻译',label:'活跃核糖体',unit:'active',icon:'shapes',color:'#b77752',description:'当前参与蛋白质合成的活跃核糖体数量。三维场景中的核糖体是代表性抽样。'},
 {id:'atp',title:'代谢',label:'ATP 分子数',unit:'molecules',icon:'zap',color:'#9a995d',description:'胞质 ATP 的分子计数。这不是百分比能量值；ATP 与 ADP 均来自 bulk 分子池。'},
 {id:'forks',title:'复制',label:'复制叉数量',unit:'forks',icon:'dna',color:'#8a7099',description:'复制叉的数量与基因组坐标。拟核的三维卷曲只用于结构解释，不是预测的空间轨迹。'},
];
const state={run:'baseline',rows:[],manifest:null,time:0,playing:false,speed:10,selected:null,events:[],fields:{},detail:null,ready:false};let view,capabilities,toastTimer,polling=false;
const timeLabel=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const format=(value,id,compact=true)=>{if(value==null||!Number.isFinite(value))return '—';if(id==='mass'||id==='volume'||id.endsWith('_mass'))return value.toFixed(id==='volume'?2:1);if(compact&&value>=1e6)return (value/1e6).toFixed(2)+'M';return Math.round(value).toLocaleString('en-US');};
function rowAt(t=state.time){const a=state.rows;if(!a.length)return null;let lo=0,hi=a.length-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(a[mid].time<=t)lo=mid;else hi=mid-1;}return a[lo];}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
async function api(path,options){const res=await dataFetch('/api'+path,options);let data=await res.json();if(!res.ok)throw new Error(typeof data.detail==='string'?data.detail:'请求参数无效');return data;}
function modal(id){$(id).showModal();icons();}
for(const dialog of document.querySelectorAll('dialog')){dialog.querySelector('.close-dialog')?.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
$('#component-list').innerHTML=components.map(c=>`<button class="component" data-component="${c.id}" aria-label="选择${c.name}"><span class="swatch" style="background:${c.color}"></span>${c.name}<span class="component-en">${c.en}</span></button>`).join('');
$('#metric-grid').innerHTML=metrics.map(m=>`<button class="metric-card" data-metric="${m.id}" aria-label="查看${m.title}详情"><div class="metric-top"><span><i data-lucide="${m.icon}"></i>${m.title}<span style="opacity:.6"> / ${m.label}</span></span><i data-lucide="arrow-up-right"></i></div><span class="metric-value" id="value-${m.id}">—</span><span class="metric-unit">${m.unit}</span><canvas id="spark-${m.id}" width="400" height="60" aria-label="${m.label}时间曲线"></canvas></button>`).join('');icons();
function select(id){state.selected=id;view?.select(id);$('#selection-card').hidden=!id;$('#isolate').disabled=!id;$('#isolate').setAttribute('aria-pressed','false');document.querySelectorAll('.component').forEach(b=>b.classList.toggle('active',b.dataset.component===id));if(!id)return;const c=components.find(c=>c.id===id);$('#selected-type').textContent=c.en;$('#selected-name').textContent=c.name;$('#selected-description').textContent=c.description;$('#selected-unit').textContent=c.unit;$('#selected-note').textContent=id==='membrane'?'体积来自模型；几何形状为示意':'模型量 · 代表性结构，位置为示意';$('#selected-note').textContent+=' · 其他组成可见度可通过滑条调节。';updateSelection();}
function updateSelection(){if(state.selected){const c=components.find(c=>c.id===state.selected);$('#selected-value').textContent=format(rowAt()?.[c.field],c.field);}renderSubtypes();}
function renderSubtypes(){const row=rowAt(),id=state.selected,panel=$('#subtype-panel');panel.hidden=!['rna','protein'].includes(id);if(panel.hidden)return;const values=id==='rna'?row?.rna_classes:row?.protein_types;$('#subtype-title').textContent=id==='rna'?'RNA 分类 · 质量':'蛋白质分类 · 单体当量';const legend=$('#subtype-legend');legend.replaceChildren();if(!values){$('#subtype-note').textContent='本次输出未包含分类数据。';return;}const items=id==='rna'?[['mRNA','mRNA','#b96891'],['tRNA','tRNA','#54998b'],['rRNA','rRNA','#8771bd'],['other','其他 RNA','#b99b61']]:[...(capabilities?.genes||[]).map(g=>[g.symbol,g.symbol,g.color]),['other','其他蛋白质','#c6a158']];for(const [key,label,color]of items){const line=document.createElement('div');line.className='subtype-row';const name=document.createElement('span'),swatch=document.createElement('i'),value=document.createElement('b');swatch.style.background=color;name.append(swatch,document.createTextNode(label));value.textContent=id==='rna'?((values[key]??0).toFixed(3)+' fg'):format(values[key],key,false);line.append(name,value);legend.append(line);}$('#subtype-note').textContent='颜色表示类别；图形数量不按实际比例。'+(id==='protein'?'单体当量包含复合物中的亚基。':'');}

document.querySelectorAll('.component').forEach(b=>b.onclick=()=>select(b.dataset.component));
$('#clear-selection').onclick=()=>select(null);$('#focus-selection').onclick=()=>view?.focusSelected();$('#selection-detail').onclick=()=>{const c=components.find(c=>c.id===state.selected);if(c)showDetail(c.metric);};
function drawChart(canvas,field,color,large=false){const cx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;cx.clearRect(0,0,w,h);const data=state.rows.filter(r=>r[field]!=null&&Number.isFinite(r[field]));if(data.length<2)return;const left=large?65:2,right=large?25:2,top=large?20:6,bottom=large?25:5;let min=Infinity,max=-Infinity;for(const r of data){min=Math.min(min,r[field]);max=Math.max(max,r[field]);}const span=Math.max(max-min,max*.025,1);min-=span*.16;max+=span*.16;const end=state.rows.at(-1).time||1;const x=t=>left+t/end*(w-left-right),y=v=>top+(1-(v-min)/(max-min))*(h-top-bottom);
 if(large){cx.font='18px ui-monospace,monospace';cx.fillStyle='#9c8b77';cx.textAlign='right';for(let i=0;i<4;i++){const v=min+(max-min)*i/3;cx.beginPath();cx.moveTo(left,y(v));cx.lineTo(w-right,y(v));cx.strokeStyle='#ddd3c3';cx.lineWidth=1;cx.stroke();cx.fillText(format(v,field),left-10,y(v)+5);}}
 // Per-pixel min/max envelope retains spikes at high playback compression.
 const buckets=new Map();for(const r of data){const k=Math.floor(x(r.time));const b=buckets.get(k)||{first:r,last:r,min:r,max:r};b.last=r;if(r[field]<b.min[field])b.min=r;if(r[field]>b.max[field])b.max=r;buckets.set(k,b);}
 const samples=[];for(const b of buckets.values()){const unique=[...new Set([b.first,b.min,b.max,b.last])].sort((a,b)=>a.time-b.time);samples.push(...unique);}
 cx.beginPath();for(let i=0;i<samples.length;i++){const r=samples[i];if(i===0)cx.moveTo(x(r.time),y(r[field]));else if(['forks','rna','ribosomes','atp'].includes(field)){cx.lineTo(x(r.time),y(samples[i-1][field]));cx.lineTo(x(r.time),y(r[field]));}else cx.lineTo(x(r.time),y(r[field]));}cx.strokeStyle=color;cx.lineWidth=large?2.5:1.8;cx.stroke();
 const current=rowAt();if(current?.[field]!=null){const xp=x(state.time),yp=y(current[field]);cx.beginPath();cx.moveTo(xp,top);cx.lineTo(xp,h-bottom);cx.strokeStyle=color+'55';cx.lineWidth=1;cx.stroke();cx.beginPath();cx.arc(xp,yp,large?4.5:3,0,Math.PI*2);cx.fillStyle=color;cx.fill();}
}
function updateMetrics(){const row=rowAt();for(const m of metrics){$('#value-'+m.id).textContent=format(row?.[m.id],m.id);drawChart($('#spark-'+m.id),m.id,m.color);}updateSelection();if(state.detail&&$('#detail-dialog').open)renderDetail();view?.state(row);}
function renderTime(){const end=state.rows.at(-1)?.time||0;$('#time-current').textContent=timeLabel(state.time);$('#time-top').textContent=timeLabel(state.time);$('#time-total').textContent='/ '+timeLabel(end);$('#time-slider').max=Math.max(1,end);$('#time-slider').value=state.time;$('#time-mid').textContent=timeLabel(end/2);$('#time-end').textContent=state.manifest?.divided?'分裂前 · '+timeLabel(end):timeLabel(end);$('#play').setAttribute('aria-label',state.playing?'暂停':'播放');}
function setPlaying(value){state.playing=value;$('#play').innerHTML=`<i data-lucide="${value?'pause':'play'}"></i>`;$('#play').setAttribute('aria-label',value?'暂停':'播放');icons();}
function setTime(t){const end=state.rows.at(-1)?.time||0;state.time=Math.max(0,Math.min(end,Number(t)||0));renderTime();updateMetrics();}
$('#play').onclick=()=>{if(!state.rows.length){toast('模型正在初始化，请稍候');return;}if(!state.playing&&state.time>=state.rows.at(-1).time&&state.manifest.status==='completed')setTime(0);setPlaying(!state.playing);};$('#time-slider').oninput=e=>setTime(e.target.value);$('#speed').onchange=e=>state.speed=Number(e.target.value);$('#jump-end').onclick=()=>setTime(state.rows.at(-1)?.time||0);
$('#cutaway').oninput=e=>{const value=Number(e.target.value);$('#cut-value').value=value+'%';view?.setCut(value/100);};$('#explode').onclick=()=>{const on=$('#explode').getAttribute('aria-pressed')!=='true';$('#explode').setAttribute('aria-pressed',on);view?.explode(on);$('#exploded-labels').hidden=!on;};$('#isolate').onclick=()=>$('#isolate').setAttribute('aria-pressed',view?.isolate());$('#home-view').onclick=()=>view?.home();$('#auto-orbit').onclick=()=>{const on=$('#auto-orbit').getAttribute('aria-pressed')!=='true';$('#auto-orbit').setAttribute('aria-pressed',on);view?.orbit(on);};$('#quality').onclick=()=>{$('#quality').textContent=view?.quality()?'HQ':'ECO';};$('#screenshot').onclick=()=>{view?.screenshot();toast('正在导出高清截图');};
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();$('#play').click();}if(e.key==='Home'){e.preventDefault();view?.home();}if(e.key==='Escape')select(null);if(e.key.toLowerCase()==='f')view?.focusSelected();});
function showDetail(id){state.detail=id;renderDetail();modal('#detail-dialog');}
function renderDetail(){const m=metrics.find(m=>m.id===state.detail),row=rowAt();$('#detail-title').textContent=m.title+' · '+m.label;$('#detail-description').textContent=m.description;$('#detail-current').innerHTML=`${format(row?.[m.id],m.id,false)}<small>${m.unit} · ${timeLabel(state.time)}</small>`;drawChart($('#detail-chart'),m.id,m.color,true);$('#detail-end').textContent=timeLabel(state.rows.at(-1)?.time||0);$('#detail-source').textContent=`数据来源：${state.fields[m.id]?.source||'等待数据'} · ${state.run} · 数值取当前时刻之前最近的实际采样，不跨事件插值。`;
 let extra='';if(row){if(m.id==='mass')extra=`总体积 ${format(row.volume,'volume')} fL · 总质量 ${format(row.cell_mass,'cell_mass')} fg · 蛋白质 ${format(row.protein_mass,'protein_mass')} fg · RNA ${format(row.rna_mass,'rna_mass')} fg`;if(m.id==='rna')extra=`活跃 RNA 聚合酶 ${format(row.rnap,'rnap')} 个`+(row.target_rna!=null?` · 目标 ${state.manifest.target?.symbol} mRNA ${row.target_rna} 个`:'');if(m.id==='ribosomes')extra=`当前蛋白质质量 ${format(row.protein_mass,'protein_mass')} fg。画面中的核糖体按代表性密度显示，不逐一对应全部活跃实体。`;if(m.id==='atp')extra=`ADP ${format(row.adp,'adp',false)} 分子 · ATP/ADP ${row.adp?(row.atp/row.adp).toFixed(2):'—'}（派生比值）`;if(m.id==='forks')extra=`完整染色体 ${format(row.chromosomes,'chromosomes')} 个 · 复制叉坐标 ${row.fork_coordinates.join(', ')} bp（基因组坐标）`+(state.events.length?' · '+state.events.map(e=>`${e.label} ${timeLabel(e.time)}`).join(' / '):'');}$('#detail-extra').textContent=extra;}
document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>showDetail(b.dataset.metric));
function updateProvenance(){const m=state.manifest;$('#provenance').textContent=m?`vEcoli ${m.model_version} · ${m.model_commit}\n实验：${m.label} · seed ${m.request.seed}\n状态：${m.status} · 已计算 ${timeLabel(m.computed_until||0)}\n参数摘要：${m.sim_data_hash||m.base_parameter_hash||'初始化中'}`:'正在连接模型';$('#provenance').style.whiteSpace='pre-line';}
$('#source-open').onclick=$('#help-open').onclick=()=>{updateProvenance();modal('#source-dialog');};
function renderGenePresets(){const list=$('#gene-presets');list.replaceChildren();for(const gene of capabilities.genes){const button=document.createElement('button');button.type='button';button.dataset.gene=gene.symbol;button.setAttribute('aria-pressed',String($('#gene').value===gene.symbol));const strong=document.createElement('strong');strong.textContent=gene.symbol;const span=document.createElement('span');span.textContent=gene.title_zh;button.append(strong,span);button.onclick=()=>{$('#gene').value=gene.symbol;updateGeneHelp();};list.append(button);}updateGeneHelp();}
function updateGeneHelp(){const value=$('#gene').value.trim().toLowerCase(),g=capabilities?.genes.find(g=>[g.symbol.toLowerCase(),g.gene_id.toLowerCase()].includes(value));$('#gene-help').textContent=g?`${g.symbol} · ${g.gene_id} — ${g.description_zh}`:'请选择一个基因或输入名称。';document.querySelectorAll('[data-gene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.gene===g?.symbol)));}
$('#gene').addEventListener('input',updateGeneHelp);
document.querySelectorAll('[data-condition]').forEach(b=>b.onclick=()=>{$('#experiment-type').value='condition';$('#condition').value=b.dataset.condition;updateExperimentFields();});
function updateExperimentFields(){const gene=$('#experiment-type').value==='expression';$('#gene-fields').hidden=!gene;$('#condition-field').hidden=gene;$('#experiment-explanation').textContent=gene?'修改已验证的单基因转录单元表达参数，并重新归一化。从细胞出生开始运行；不是基因敲除。':'从细胞出生开始，使用固定随机种子运行。匹配的已计算结果将直接打开。';}
$('#experiment-type').onchange=updateExperimentFields;
async function jobs(){try{const runs=await api('/runs');$('#job-list').replaceChildren();for(const run of runs){const div=document.createElement('div');div.className='job-item';const label=document.createElement('span');label.textContent=run.label+' · '+({completed:'已完成',running:'运行中',initializing:'初始化',queued:'等待中',failed:'失败',cancelled:'已取消'}[run.status]||run.status);const button=document.createElement('button');button.type='button';button.textContent='查看';button.onclick=()=>{loadRun(run.id);$('#experiment-dialog').close();};div.append(label,button);if(['running','initializing'].includes(run.status)&&run.id!=='baseline'){const cancel=document.createElement('button');cancel.type='button';cancel.textContent='取消';cancel.onclick=async()=>{try{await api('/runs/'+run.id+'/cancel',{method:'POST'});jobs();}catch(e){toast(e.message);}};div.append(cancel);}$('#job-list').append(div);}}catch(e){toast(e.message);}}
$('#experiment-open').onclick=()=>{modal('#experiment-dialog');jobs();};$('#baseline').onclick=()=>{loadRun('baseline');$('#experiment-dialog').close();};
$('#experiment-form').onsubmit=async e=>{e.preventDefault();$('#experiment-error').hidden=true;$('#start-experiment').disabled=true;try{const request={kind:$('#experiment-type').value,condition:$('#condition').value,gene:$('#gene').value.trim(),factor:Number($('#factor').value),duration:Number($('#duration').value),seed:0};const result=await api('/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)});await loadRun(result.id);$('#experiment-dialog').close();toast(result.cached?'已打开匹配的计算结果':'实验已开始，可边算边看');}catch(err){$('#experiment-error').textContent=err.message;$('#experiment-error').hidden=false;}finally{$('#start-experiment').disabled=false;}};
let loadEpoch=0;
async function loadRun(id){const epoch=++loadEpoch;setPlaying(false);state.run=id;state.rows=[];state.time=0;state.events=[];state.manifest=null;setTime(0);try{const data=await api('/runs/'+id+'/data');if(epoch!==loadEpoch)return;applyData(data,true);if(state.rows.length)setPlaying(true);}catch(e){toast(e.message);}}
function applyData(data,replace=false){state.manifest=data.manifest;state.fields=data.fields;state.events=data.events;if(replace)state.rows=data.rows;else{const end=state.rows.at(-1)?.time??-1;state.rows.push(...data.rows.filter(r=>r.time>end));}const m=state.manifest;$('#condition-label').textContent=m.label;$('#data-badge').textContent=m.status==='completed'?'vEcoli · 真实数据回放':m.status==='failed'?'模型运行失败':'vEcoli · 边算边看';$('#run-status').textContent=`CELL 0 / GEN 1 · ${m.status==='completed'?(m.divided?'已完成 · 已分裂':'已完成'):m.status==='failed'?'计算失败':m.status==='cancelled'?'已取消':`计算中 ${m.speed?m.speed+'×':''}`}`;$('#scene-subtitle').textContent=m.target?`${m.target.symbol} 表达参数 ${m.target.factor}× · 从出生开始`:'旋转、探索，观察生命过程。';$('#activity-caption').innerHTML=`${state.rows.length?'来自当前仿真时刻':'等待模型首个采样'} <i data-lucide="arrow-down-right"></i>`;renderTime();updateMetrics();icons();}
async function poll(){if(polling)return;polling=true;const id=state.run,epoch=loadEpoch;try{const data=await api('/runs/'+id+'/data?after='+(state.rows.at(-1)?.time??-1));if(epoch===loadEpoch)applyData(data);}catch(e){$('#run-status').textContent='连接中断 · 正在重连';}finally{polling=false;}}
let last=performance.now(),lastDisplay=0;function tick(now){const dt=Math.min(.25,(now-last)/1000);last=now;if(state.playing&&state.rows.length){const end=state.rows.at(-1).time;state.time=Math.min(end,state.time+dt*state.speed);if(state.time>=end&&['completed','failed','cancelled'].includes(state.manifest?.status)){setPlaying(false);if(state.manifest.divided)toast('细胞已分裂 · 当前母细胞回放结束');}if(now-lastDisplay>120){renderTime();updateMetrics();lastDisplay=now;}}requestAnimationFrame(tick);}requestAnimationFrame(tick);
try{view=await createCellView($('#scene'),{onSelect:select,onHover:(id,x,y)=>{const el=$('#hover-label');el.hidden=!id;if(id){el.textContent=components.find(c=>c.id===id).name;el.style.left=Math.min(x+15,$('#scene').clientWidth-160)+'px';el.style.top=Math.min(y+15,$('#scene').clientHeight-60)+'px';}},onReady:()=>state.ready=true});}catch(e){$('#scene-loading').innerHTML='<span>三维渲染未能启动，请启用浏览器硬件加速后刷新。数据面板仍可使用。</span>';console.error(e);}
try{capabilities=await api('/capabilities');$('#gene-list').innerHTML=capabilities.genes.map(g=>`<option value="${g.symbol}">${g.gene_id}</option>`).join('');$('#gene').placeholder='例如 pgi（EG10702）';view?.setGenePresets(capabilities.genes);renderGenePresets();}catch(e){toast('模型服务暂不可用，正在重连');}
await loadRun('baseline');setInterval(poll,2500);
window.observatory={state,view,setTime,select,loadRun,ready:()=>state.ready,metrics};
if(document.modelContext?.registerTool){const life=new AbortController();for(const tool of [
{name:'read_cell_state',description:'Read the currently viewed vEcoli sample and representation.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({run:state.run,time:state.time,sample:rowAt(),representation:'Model quantities; illustrative spatial layout'})},
{name:'set_playback_time',description:'Navigate within already computed biological time, in seconds.',inputSchema:{type:'object',properties:{seconds:{type:'number',minimum:0}},required:['seconds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input.seconds!=='number'||input.seconds<0||input.seconds>(state.rows.at(-1)?.time||0))throw new Error('Time outside computed range');setTime(input.seconds);return {time:state.time};}},
]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}

bindContextOpacity(()=>view);
